func (r *MCPServerResourceModel) ToSharedMCPServerServiceUpdateRequest(ctx context.Context) (*shared.MCPServerServiceUpdateRequest, diag.Diagnostics) {
	var diags diag.Diagnostics

	mcpServer, mcpServerDiags := r.ToSharedMCPServerViewInput(ctx)
	diags.Append(mcpServerDiags...)

	if diags.HasError() {
		return nil, diags
	}

	updateMask := "displayName,description,dataSensitivity,toolPrefix"
	mcpServer.RequireToolApproval = nil
	if approval := r.configuredToolApproval(); approval != nil && !approval.IsNull() && !approval.IsUnknown() {
		value := shared.RequireToolApproval(approval.ValueString())
		mcpServer.RequireToolApproval = &value
		updateMask += ",requireToolApproval"
	}
	out := shared.MCPServerServiceUpdateRequest{
		McpServer:  mcpServer,
		UpdateMask: &updateMask,
	}

	return &out, diags
}

